    color: { title: "前景色与背景色", body: "上方色块是当前颜色，点开是调色板，长按可调出快速色轮；右侧小方块切换前景/背景（正在真的交换一次）。" },
    orbMain: { title: "工具球", body: "点按展开常用工具环，按住可拖到顺手的位置；停靠到边缘后会记住位置。" },
    orbSel: { title: "选区球", body: "选中区域后，选区球提供填充、复制、剪切、粘贴、翻转、反选等操作。" },
    orbPal: { title: "取色球", body: "展开扇形色板；旁边的胶囊可在“色板 / 画布颜色 / 最近使用”之间切换（正在真的切换给你看）。" },
    canvasRefs: { title: "引用画布 / 提取图层", body: "「引用画布」会弹出一页所有画布的缩略图，先选引用方式：**按图层引用**（默认）会给源画布的每个图层各生成一条引用图层，在它上面画就改到源画布对应的那条图层，不会猜错；**合并为一条**则只引用整张画面。引用层是实时联动的，源画布改了这里立刻更新；图层行上的 ⚭ 表示这是引用层，在图层面板点「解除引用」会保留像素并断开关系。「提取为画布」把当前图层（含它的所有帧）移出去变成一张新画布。" },
    orbCanvas: { title: "画布球", body: "画布球管的是「当前聚焦的那张画布」：常用页有新建、重命名、改尺寸、保存（存成它自己的 .pxc 文件）和关闭并保存；点「更多」还能预览、调整色相、导出、适配画布和设置平铺。点画布上方的标题栏可以切换聚焦，双击标题会平滑放大到适配大小。" },
    tileModes: { title: "平铺方式", body: "平铺让画布四周显示副本，只有中间那张能画——做无缝瓦片或背景时一眼就能看到接缝。这里有四种：关闭、横向（左右各一份）、竖向（上下各一份）、九宫格（3×3）。" },
    bucketGrad: { title: "油漆桶渐变", body: "底部栏这个按钮切换纯色/渐变填充。渐变模式下按住并拖动来定方向和长度（画布上会出现黄色方向线），松手才真正落笔；底部栏的颗粒按钮循环 RGB 平滑 / 2×2 / 4×4 / 8×8。" },
    orbFx: { title: "魔法球", body: "一键完成描边、投影、外发光、反色、灰度、居中与智能裁剪等特效。这些都会改动画面，所以这里只逐个高亮可用特效，不真的应用。" },
    timeline: { title: "图层与帧", body: "底部矩阵是图层×帧：横排是帧、竖排是图层，点格子即可切换要编辑的图层与帧。帧号格：点一下切帧，长按弹出该帧时长，长按后左右拖动可重排帧。" },
    layerDrag: { title: "拖拽重排", body: "长按图层行约 0.3 秒后上下拖动可调整图层顺序；帧号格同样可左右拖动重排。" },
    onion: { title: "洋葱皮", body: "开启后会淡淡显示前后帧作参考，前后帧数与不透明度可在设置里调整（至少要有 2 帧才有参考）。开启“循环环绕”后，首帧的前一帧显示末尾帧、末帧的后一帧显示开头帧，并用蓝色/琥珀色区分。" },
    menu: { title: "主菜单", body: "菜单里有新建工程、打开/导入、设置、更新日志与新手引导等入口；新建工程或打开会替换当前作品，建议先保存。想在同一个工程里再开一张画布，用画布球的「新建画布」。" },
    save: { title: "保存工程（唯一文件）", body: "保存为 .pxc 工程文件，随时可继续编辑；应用也会自动保存并在下次打开时恢复。" },
    export: { title: "导出", body: "导出 PNG、GIF 动画或精灵表（含 JSON 数据），可选择整帧/当前图层/选区与缩放倍率。" },
    doubleTap: { title: "双击边距 = 撤销", body: "在画布外的边距区域双击即可撤销上一步（画布内双击不会误触发）。" },
    twoFingerTap: { title: "双指双击 = 重做", body: "在边距区域用两根手指同时双击即可重做刚才撤销的操作。" },
    tripleTap: { title: "三连击 = 2× 放大", body: "在画布上快速点三下，会以点击位置为中心放大 2 倍（现在真的放大给你看，稍后还原）。" },
    fourFinger: { title: "四指手势", body: "四指按住画布、其中至少两根手指滑动，抬起后即可打开“预览所有帧”；在预览里点任意一帧就能跳到该帧。" },
    coreTools: { title: "核心工具", body: "点开工具球后，这里依次是铅笔、橡皮、油漆桶、取色器，点一下即可切换（正在真的切到橡皮再切回）。" },
    shapeTools: { title: "形状工具", body: "点这个分组会展开形状子环：直线、矩形、椭圆、圆、多边形；拖动即可成形，松手后它会自动变成选区，可以直接拖动或缩放。" },
    selectTools: { title: "选区工具", body: "选区子环里是矩形框选、魔棒（按容差选同色区域）和套索；魔棒的容差可在“设置 → 工具”里调整。" },
    controls: { title: "控制栏其它按钮", body: "这里还有交换前景/背景色、色相/饱和度/明度调整、对称绘画开关，以及图形工具的“从中心绘制”按钮（正在真的开启一次对称轴）。" },
    topbar: { title: "顶部工具栏", body: "从左到右：菜单、操作记录、撤销、重做、导出、保存、时间轴、尺寸、全屏。" },
    undo: { title: "撤销与重做", body: "撤销/重做按钮；旁边的“操作记录”能查看全部步骤并跳到任意一步。" },
    menuSave: { title: "菜单里的保存", body: "这里同样可以保存工程，效果与顶部保存按钮一致。" },
