    canvasRefs: { title: "Reference / extract", body: "Reference canvas opens a page of thumbnails. Pick a mode first: Per layer (default) creates one live layer for every layer of the source, and painting on one edits exactly that source layer instead of guessing; Flattened mirrors the whole canvas in a single layer. Either way the link is live, so edits over there show up here immediately. A layer row marked ⚭ is a reference; Release reference in the layer panel keeps the pixels and breaks the link. Extract to canvas moves the current layer (all its frames) out into a canvas of its own." },
    orbCanvas: { title: "Canvas orb", body: "The canvas orb acts on the FOCUSED canvas. Page 1: new, rename, resize, save (writes its own .pxc file) and close & save. Tap More for preview, colour adjust, export, fit and tiling. Tap a canvas title bar to focus it; double-tap a title to smoothly zoom it to fit." },
    tileModes: { title: "Tiling modes", body: "Tiling shows copies around the canvas so the seams of a seamless tile or background are obvious; only the centre copy is editable. Four modes: off, horizontal (one copy each side), vertical (one above and below) and 3x3 grid." },
    bucketGrad: { title: "Bucket gradient", body: "This bottom-bar button switches the bucket between flat and gradient fill. In gradient mode press and drag to set the direction and length (a yellow guide appears on the canvas) and the pixels are only written on release. The step chip cycles RGB smooth / 2x2 / 4x4 / 8x8." },
    orbFx: { title: "Magic orb", body: "One tap for outline, drop shadow, glow, invert, grayscale, centring and smart crop. They all change the artwork, so this step only lights up the available effects instead of applying one." },
    timeline: { title: "Layers & frames", body: "The bottom matrix is layers × frames: columns are frames, rows are layers — tap a cell to switch what you edit. On a frame number: tap to switch frame, hold to set that frame's duration, hold and drag sideways to reorder frames." },
    layerDrag: { title: "Drag to reorder", body: "Hold a layer row for ~0.3s then drag vertically to reorder layers; frame numbers reorder the same way horizontally." },
    onion: { title: "Onion skin", body: "Shows faint neighbours as reference; how many frames and their opacity live in Settings (you need at least 2 frames to see anything). With loop-aware onion skin on, the frame before the first one is the last one and the frame after the last is the first, tinted blue / amber." },
    menu: { title: "Main menu", body: "New project, open/import, settings, release notes and this guide all live here. New project or open replaces the current artwork, so save first; to add another canvas inside the same project use New canvas in the canvas ball." },
    save: { title: "Save project (the only file)", body: "Saves a .pxc project you can reopen any time; the app also autosaves and restores on the next launch." },
    export: { title: "Export", body: "Export PNG, animated GIF or a spritesheet (with JSON data), choosing whole frame / current layer / selection and scale." },
    doubleTap: { title: "Double-tap margin = undo", body: "Double-tap the margin outside the canvas to undo (double-taps inside the canvas never trigger it)." },
    twoFingerTap: { title: "Two-finger double-tap = redo", body: "Double-tap the margin with two fingers at once to redo what you just undid." },
