    fourFinger: { title: "Four-finger gesture", body: "Hold four fingers on the canvas and slide at least two of them, then lift to open the all-frames preview; tap any frame in it to jump there." },
    coreTools: { title: "Core tools", body: "With the tool ring open: pencil, eraser, bucket and eyedropper — tap one to switch (it really switches to the eraser and back)." },
    shapeTools: { title: "Shape tools", body: "This group opens the shape sub-ring: line, rectangle, ellipse, circle and polygon. Drag to draw, then move or scale it." },
    selectTools: { title: "Selection tools", body: "The selection sub-ring holds rectangular marquee, magic wand (tolerance-based) and lasso; the wand tolerance lives in Settings → Tools." },
    controls: { title: "Other control-bar buttons", body: "Swap foreground/background, open the hue/saturation/lightness adjuster, toggle drawing symmetry and switch shapes to draw from the centre (it really turns one symmetry axis on and off)." },
    topbar: { title: "Top toolbar", body: "Left to right: menu, history, undo, redo, export, save, timeline, resize, fullscreen." },
    undo: { title: "Undo & redo", body: "Undo/redo buttons; the history button next to them lists every step and lets you jump to any of them." },
    menuSave: { title: "Save in the menu", body: "Saves the project here too — same as the toolbar save button." },
    menuImport: { title: "Import", body: "Opens a sub-menu: image, spritesheet, reference image or palette." },
    importImg: { title: "Import image", body: "Opens an image as a new project (replaces the current artwork, so save first)." },
    importSheet: { title: "Import spritesheet", body: "Slices a grid image into animation frames by cell size, so fill in the columns/rows or the cell width and height first." },
    refImg: { title: "Reference image", body: "Floats the image over the canvas as a reference you can pick colours from." },
    menuExport: { title: "Export sub-menu", body: "Opens a sub-menu: the export dialog, or just the palette." },
    exportDialog: { title: "Export dialog", body: "Pick the export scope, scale and format, then save to a file; GIF and spritesheet can also limit which frames are written." },
    exportPalette: { title: "Export palette", body: "Saves the current palette as a .gpl file for use in other software." },
    menuSettings: { title: "Settings", body: "This is the real Settings window: grid, onion skin, history and autosave all live here — scroll through it, or use the search box and the settings import/export at the top." },
    menuChangelog: { title: "Release notes", body: "This is the real release-notes window; the version list scrolls through the history." },
    menuGuide: { title: "Onboarding guide", body: "Tap here to watch the tour again — you can replay all steps any time." },
    frameSel: { title: "Pick frames", body: "Tap this button to start picking: tap frame numbers to tick several (tap again to untick), then duplicate, delete or set one duration for all of them." },
    paletteOps: { title: "Tidy the palette", body: "The sort menu at the right of the tabs switches between by-hue and by-lightness (order only, artwork untouched), and the icon button next to it de-dupes. The + on a preset row merges that palette into the current one (tapping the row replaces it), you can save the current palette as your own preset, and tapping the blank part of the panel closes it." },
    exportRange: { title: "Export frame range", body: "GIF, spritesheet and per-layer exports can write just a slice: set the first and last frame, or tap All frames; when frames are picked in the timeline you can reuse that range." },
    settingsSearch: { title: "Search & reset", body: "The search box at the top filters settings by name or description; a reset button appears on rows you changed; you can also export the whole set to a file and import it back. Brush tip, shape defaults and every touch threshold live here too." },
    back: { title: "Back gesture", body: "The system back gesture closes one layer at a time: dialog -> panel -> floating-ball ring -> tour. With nothing open the first press only warns, and a second press exits the app." },
    gestures: { title: "Re-map any gesture", body: "In Settings -> Gestures & Touch every gesture can run a different function: double-tap the margin or the canvas, two-finger double-tap, triple-tap, four-finger slide and long-press can each be undo / redo / zoom / fit / play / onion / grid / symmetry / timeline / preview / pick colour." },
    history: { title: "History travels with the project", body: "Saving a .pxc stores the undo/redo stack too, so you can keep undoing after reopening it; Settings -> Data can turn the recording off to keep files small." },
